begin;
alter table public.profiles add column if not exists nationality text, add column if not exists hometown text;
create table if not exists public.caleris_driver_attributes(member_id uuid primary key references public.members(id) on delete cascade,attributes jsonb not null default '{"race_pace":50,"qualifying_pace":50,"experience":50,"aggression":50,"defensive_strength":50,"overtake_skill":50,"mistake_rate":50,"tyre_management":50}'::jsonb,updated_by uuid references auth.users(id) on delete set null,updated_at timestamptz not null default now());
create table if not exists public.caleris_team_profiles(team_id uuid primary key references public.teams(id) on delete cascade,logo_url text,country_of_origin text,base_location text,founded_year integer check(founded_year is null or founded_year between 1800 and 2200),history text,updated_by uuid references auth.users(id) on delete set null,updated_at timestamptz not null default now());
create table if not exists public.caleris_achievements(id uuid primary key default gen_random_uuid(),target_kind text not null check(target_kind in ('member','team')),member_id uuid references public.members(id) on delete cascade,team_id uuid references public.teams(id) on delete cascade,title text not null,description text,season_id uuid references public.license_seasons(id) on delete set null,awarded_at timestamptz not null default now(),created_by uuid references auth.users(id) on delete set null,constraint caleris_achievement_target_check check((target_kind='member' and member_id is not null and team_id is null) or (target_kind='team' and team_id is not null and member_id is null)));
create table if not exists public.caleris_engines(id uuid primary key default gen_random_uuid(),name text not null unique,manufacturer text,country_of_origin text,description text,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.caleris_team_engines(id uuid primary key default gen_random_uuid(),season_id uuid not null references public.license_seasons(id) on delete cascade,team_id uuid not null references public.teams(id) on delete cascade,engine_id uuid not null references public.caleris_engines(id) on delete restrict,assigned_at timestamptz not null default now(),assigned_by uuid references auth.users(id) on delete set null,unique(season_id,team_id));
create table if not exists public.caleris_race_result_entries(id uuid primary key default gen_random_uuid(),round_id uuid not null references public.license_rounds(id) on delete cascade,member_id uuid not null references public.members(id) on delete restrict,team_id uuid references public.teams(id) on delete set null,finish_status text not null check(finish_status in ('finished','dnf','dns','dsq')),finishing_position integer check(finishing_position is null or finishing_position>0),note text,recorded_by uuid references auth.users(id) on delete set null,recorded_at timestamptz not null default now(),unique(round_id,member_id),constraint caleris_race_result_position_check check((finish_status='finished' and finishing_position is not null) or (finish_status<>'finished' and finishing_position is null)));
create table if not exists public.caleris_announcements(id uuid primary key default gen_random_uuid(),title text not null,body text not null,category text not null default 'general',division_key text,season_id uuid references public.license_seasons(id) on delete set null,is_published boolean not null default false,published_at timestamptz,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.caleris_regulations(id uuid primary key default gen_random_uuid(),title text not null,body text not null,scope_kind text not null check(scope_kind in ('permanent','seasonal')),division_key text,season_id uuid references public.license_seasons(id) on delete set null,version_label text,is_published boolean not null default false,published_at timestamptz,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint caleris_regulation_scope_check check((scope_kind='permanent' and season_id is null) or (scope_kind='seasonal' and season_id is not null)));
create table if not exists public.caleris_job_adverts(id uuid primary key default gen_random_uuid(),team_id uuid not null references public.teams(id) on delete cascade,season_id uuid references public.license_seasons(id) on delete set null,division_key text,title text not null,description text not null,requirements text,open_seats integer not null default 1 check(open_seats>0),available_from date,status text not null default 'published' check(status in ('draft','published','closed')),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.caleris_appeals(id uuid primary key default gen_random_uuid(),fine_id uuid not null references public.caleris_fines(id) on delete cascade,target_kind text not null check(target_kind in ('member','team')),target_member_id uuid references public.members(id) on delete set null,target_team_id uuid references public.teams(id) on delete set null,appeal_statement text not null,status text not null default 'pending' check(status in ('pending','approved','rejected')),fia_decision text,submitted_by uuid references auth.users(id) on delete set null,decided_by uuid references auth.users(id) on delete set null,submitted_at timestamptz not null default now(),decided_at timestamptz,constraint caleris_appeal_target_check check((target_kind='member' and target_member_id is not null and target_team_id is null) or (target_kind='team' and target_team_id is not null and target_member_id is null)));
create unique index if not exists caleris_appeals_one_pending_per_fine_idx on public.caleris_appeals(fine_id) where status='pending';
create index if not exists caleris_appeals_status_submitted_idx on public.caleris_appeals(status,submitted_at desc);
create index if not exists caleris_race_result_entries_member_idx on public.caleris_race_result_entries(member_id,round_id);
create index if not exists caleris_race_result_entries_team_idx on public.caleris_race_result_entries(team_id,round_id);
create index if not exists caleris_team_engines_engine_idx on public.caleris_team_engines(season_id,engine_id);
create index if not exists caleris_job_adverts_status_idx on public.caleris_job_adverts(status,created_at desc);
create index if not exists caleris_achievements_member_idx on public.caleris_achievements(member_id,awarded_at desc) where member_id is not null;
create index if not exists caleris_achievements_team_idx on public.caleris_achievements(team_id,awarded_at desc) where team_id is not null;
alter table public.caleris_driver_attributes enable row level security;
alter table public.caleris_team_profiles enable row level security;
alter table public.caleris_achievements enable row level security;
alter table public.caleris_engines enable row level security;
alter table public.caleris_team_engines enable row level security;
alter table public.caleris_race_result_entries enable row level security;
alter table public.caleris_announcements enable row level security;
alter table public.caleris_regulations enable row level security;
alter table public.caleris_job_adverts enable row level security;
alter table public.caleris_appeals enable row level security;
revoke all on public.caleris_driver_attributes,public.caleris_team_profiles,public.caleris_achievements,public.caleris_engines,public.caleris_team_engines,public.caleris_race_result_entries,public.caleris_announcements,public.caleris_regulations,public.caleris_job_adverts,public.caleris_appeals from anon,authenticated,service_role,public;
grant select,insert,update,delete on public.caleris_driver_attributes,public.caleris_team_profiles,public.caleris_achievements,public.caleris_engines,public.caleris_team_engines,public.caleris_race_result_entries to authenticated;
grant select,insert,update,delete on public.caleris_announcements,public.caleris_regulations,public.caleris_job_adverts,public.caleris_appeals to authenticated;
create policy "Authenticated members read driver attributes" on public.caleris_driver_attributes for select to authenticated using(true);
create policy "Admins manage driver attributes" on public.caleris_driver_attributes for all to authenticated using(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid())));
create policy "Authenticated members read team profiles" on public.caleris_team_profiles for select to authenticated using(true);
create policy "Admins manage team profiles" on public.caleris_team_profiles for all to authenticated using(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid())));
create policy "Authenticated members read achievements" on public.caleris_achievements for select to authenticated using(true);
create policy "Admins manage achievements" on public.caleris_achievements for all to authenticated using(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid())));
create policy "Authenticated members read engines" on public.caleris_engines for select to authenticated using(true);
create policy "Admins manage engines" on public.caleris_engines for all to authenticated using(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid())));
create policy "Authenticated members read team engines" on public.caleris_team_engines for select to authenticated using(true);
create policy "Admins manage team engines" on public.caleris_team_engines for all to authenticated using(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.site_admins a where a.user_id=(select auth.uid())));
create policy "Authenticated members read race classifications" on public.caleris_race_result_entries for select to authenticated using(true);
create policy "FIA and Admin manage race classifications" on public.caleris_race_result_entries for all to authenticated using(public.is_caleris_fia_or_admin()) with check(public.is_caleris_fia_or_admin());
create policy "Members read published announcements" on public.caleris_announcements for select to authenticated using(is_published or public.is_caleris_fia_or_admin());
create policy "FIA and Admin manage announcements" on public.caleris_announcements for all to authenticated using(public.is_caleris_fia_or_admin()) with check(public.is_caleris_fia_or_admin());
create policy "Members read published regulations" on public.caleris_regulations for select to authenticated using(is_published or public.is_caleris_fia_or_admin());
create policy "FIA and Admin manage regulations" on public.caleris_regulations for all to authenticated using(public.is_caleris_fia_or_admin()) with check(public.is_caleris_fia_or_admin());
create policy "Members read published job adverts" on public.caleris_job_adverts for select to authenticated using(status='published' or exists(select 1 from public.profiles p join public.members m on m.id=p.member_id where p.user_id=(select auth.uid()) and m.role='Owner' and m.team_id=caleris_job_adverts.team_id) or exists(select 1 from public.site_admins a where a.user_id=(select auth.uid())));
create policy "Team owners publish job adverts" on public.caleris_job_adverts for insert to authenticated with check(status in ('draft','published') and exists(select 1 from public.profiles p join public.members m on m.id=p.member_id where p.user_id=(select auth.uid()) and m.role='Owner' and m.team_id=caleris_job_adverts.team_id));
create policy "Team owners update own job adverts" on public.caleris_job_adverts for update to authenticated using(exists(select 1 from public.profiles p join public.members m on m.id=p.member_id where p.user_id=(select auth.uid()) and m.role='Owner' and m.team_id=caleris_job_adverts.team_id) or exists(select 1 from public.site_admins a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.profiles p join public.members m on m.id=p.member_id where p.user_id=(select auth.uid()) and m.role='Owner' and m.team_id=caleris_job_adverts.team_id) or exists(select 1 from public.site_admins a where a.user_id=(select auth.uid())));
create policy "Team owners delete own job adverts" on public.caleris_job_adverts for delete to authenticated using(exists(select 1 from public.profiles p join public.members m on m.id=p.member_id where p.user_id=(select auth.uid()) and m.role='Owner' and m.team_id=caleris_job_adverts.team_id) or exists(select 1 from public.site_admins a where a.user_id=(select auth.uid())));
create policy "Targets and FIA read appeals" on public.caleris_appeals for select to authenticated using(public.is_caleris_fia_or_admin() or (target_kind='member' and exists(select 1 from public.profiles p where p.user_id=(select auth.uid()) and p.member_id=caleris_appeals.target_member_id)) or (target_kind='team' and exists(select 1 from public.profiles p join public.members m on m.id=p.member_id where p.user_id=(select auth.uid()) and m.role='Owner' and m.team_id=caleris_appeals.target_team_id)));
create policy "Punished drivers and team owners submit appeals" on public.caleris_appeals for insert to authenticated with check(status='pending' and submitted_by=(select auth.uid()) and ((target_kind='member' and exists(select 1 from public.profiles p join public.members m on m.id=p.member_id join public.caleris_fines f on f.id=caleris_appeals.fine_id where p.user_id=(select auth.uid()) and m.role='Driver' and p.member_id=caleris_appeals.target_member_id and f.target_kind='member' and f.target_member_id=p.member_id)) or (target_kind='team' and exists(select 1 from public.profiles p join public.members m on m.id=p.member_id join public.caleris_fines f on f.id=caleris_appeals.fine_id where p.user_id=(select auth.uid()) and m.role='Owner' and m.team_id=caleris_appeals.target_team_id and f.target_kind='team' and f.target_team_id=m.team_id)));
create policy "FIA and Admin update appeals" on public.caleris_appeals for update to authenticated using(public.is_caleris_fia_or_admin()) with check(public.is_caleris_fia_or_admin());
create policy "Authenticated members read public season standings" on public.license_round_standings for select to authenticated using(true);
create policy "Authenticated members read final season standings" on public.license_final_standings for select to authenticated using(true);
create policy "Authenticated members read season divisions" on public.license_season_divisions for select to authenticated using(true);
create policy "Authenticated members read season rounds" on public.license_rounds for select to authenticated using(true);
create policy "Authenticated members read season registrations" on public.license_season_members for select to authenticated using(true);
create policy "Members read own wallet ledger entries" on public.economy_entries for select to authenticated using(exists(select 1 from public.economy_wallet_accounts w where w.id=economy_entries.account_id and (exists(select 1 from public.profiles p where p.user_id=(select auth.uid()) and p.member_id=w.member_id) or (w.account_kind='public_member' and w.profile_user_id=(select auth.uid())) or exists(select 1 from public.profiles p join public.members m on m.id=p.member_id where p.user_id=(select auth.uid()) and m.role='Owner' and m.team_id=w.team_id))));
create policy "Members read transactions involving own wallets" on public.economy_transactions for select to authenticated using(exists(select 1 from public.economy_wallet_accounts w where w.id=economy_transactions.source_account_id and (exists(select 1 from public.profiles p where p.user_id=(select auth.uid()) and p.member_id=w.member_id) or (w.account_kind='public_member' and w.profile_user_id=(select auth.uid())) or exists(select 1 from public.profiles p join public.members m on m.id=p.member_id where p.user_id=(select auth.uid()) and m.role='Owner' and m.team_id=w.team_id))) or exists(select 1 from public.economy_wallet_accounts w where w.id=economy_transactions.destination_account_id and (exists(select 1 from public.profiles p where p.user_id=(select auth.uid()) and p.member_id=w.member_id) or (w.account_kind='public_member' and w.profile_user_id=(select auth.uid())) or exists(select 1 from public.profiles p join public.members m on m.id=p.member_id where p.user_id=(select auth.uid()) and m.role='Owner' and m.team_id=w.team_id))));
create or replace function public.member_register_driver_for_season(p_season_division_id uuid,p_driver_member_id uuid) returns uuid language plpgsql security definer set search_path='' as $$
declare v_actor public.members%rowtype;v_team_id uuid;v_division public.license_season_divisions%rowtype;v_driver public.members%rowtype;v_registration_id uuid;
begin
if (select auth.uid()) is null then raise exception 'Authentication required.';end if;
select m.* into v_actor from public.profiles p join public.members m on m.id=p.member_id where p.user_id=(select auth.uid());
if not found or v_actor.role<>'Owner' or v_actor.team_id is null then raise exception 'Hanya Team Owner yang dapat mendaftarkan driver.';end if;
v_team_id:=v_actor.team_id;
select * into v_division from public.license_season_divisions where id=p_season_division_id;
if not found then raise exception 'Season division tidak ditemukan.';end if;
if not exists(select 1 from public.teams t where t.id=v_team_id and lower(t.division_key)=lower(v_division.division_key)) then raise exception 'Divisi pendaftaran tidak sesuai dengan divisi tim.';end if;
if not exists(select 1 from public.season_calendar_periods p where p.season_id=v_division.season_id and p.period_type='off_season' and current_date between p.starts_on and p.ends_on) then raise exception 'Pendaftaran hanya dibuka selama Off Season season tujuan.';end if;
select * into v_driver from public.members where id=p_driver_member_id;
if not found or v_driver.role<>'Driver' or v_driver.team_id is distinct from v_team_id then raise exception 'Driver harus berstatus Driver dan terikat pada tim ini.';end if;
if not exists(select 1 from public.economy_driver_contracts c where c.season_id=v_division.season_id and c.team_id=v_team_id and c.member_id=p_driver_member_id and c.status='active') then raise exception 'Driver belum memiliki kontrak aktif dengan tim untuk season tujuan.';end if;
if exists(select 1 from public.license_season_members sm where sm.season_id=v_division.season_id and sm.member_id=p_driver_member_id) then raise exception 'Driver sudah terdaftar pada season ini.';end if;
insert into public.license_season_members(season_id,season_division_id,member_id,is_hiatus,preserved_license) values(v_division.season_id,v_division.id,p_driver_member_id,false,v_driver.license) returning id into v_registration_id;
return v_registration_id;
end;$$;
revoke all on function public.member_register_driver_for_season(uuid,uuid) from public,anon,service_role;
grant execute on function public.member_register_driver_for_season(uuid,uuid) to authenticated;
create or replace function public.fia_decide_appeal(p_appeal_id uuid,p_approve boolean,p_decision text) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_appeal public.caleris_appeals%rowtype;
begin
if (select auth.uid()) is null or not public.is_caleris_fia_or_admin() then raise exception 'Hanya FIA atau Admin yang dapat memutuskan banding.';end if;
if nullif(trim(p_decision),'') is null then raise exception 'Alasan keputusan wajib diisi.';end if;
select * into v_appeal from public.caleris_appeals where id=p_appeal_id for update;
if not found then raise exception 'Banding tidak ditemukan.';end if;
if v_appeal.status<>'pending' then raise exception 'Banding sudah diputuskan.';end if;
update public.caleris_appeals set status=case when p_approve then 'approved' else 'rejected' end,fia_decision=trim(p_decision),decided_by=(select auth.uid()),decided_at=now() where id=p_appeal_id;
return jsonb_build_object('id',p_appeal_id,'status',case when p_approve then 'approved' else 'rejected' end);
end;$$;
revoke all on function public.fia_decide_appeal(uuid,boolean,text) from public,anon,service_role;
grant execute on function public.fia_decide_appeal(uuid,boolean,text) to authenticated;
create or replace function public.caleris_seed_driver_attributes() returns trigger language plpgsql security definer set search_path='' as $$
begin if new.role='Driver' then insert into public.caleris_driver_attributes(member_id) values(new.id) on conflict(member_id) do nothing;end if;return new;end;$$;
revoke all on function public.caleris_seed_driver_attributes() from public,anon,authenticated,service_role;
drop trigger if exists caleris_seed_driver_attributes_after_member_insert on public.members;
create trigger caleris_seed_driver_attributes_after_member_insert after insert or update of role on public.members for each row execute function public.caleris_seed_driver_attributes();
insert into public.caleris_driver_attributes(member_id) select m.id from public.members m where m.role='Driver' on conflict(member_id) do nothing;
commit;